class Solution {
public:
    vector<int> largestSubarray(vector<int>& nums, int k) {
        int max_idx = 0;
        int limit = nums.size() - k;
        for (int i = 1; i <= limit; i++) {
            if (nums[i] > nums[max_idx]) {
                max_idx = i;
            }
        }
        return vector<int>(nums.begin() + max_idx, nums.begin() + max_idx + k);
    }
};

class Solution {
    public int[] largestSubarray(int[] nums, int k) {
        int maxIdx = 0;
        int limit = nums.length - k;
        for (int i = 1; i <= limit; i++) {
            if (nums[i] > nums[maxIdx]) {
                maxIdx = i;
            }
        }
        int[] res = new int[k];
        System.arraycopy(nums, maxIdx, res, 0, k);
        return res;
    }
}

var largestSubarray = function(nums, k) {
    let maxIdx = 0;
    const limit = nums.length - k;
    for (let i = 1; i <= limit; i++) {
        if (nums[i] > nums[maxIdx]) {
            maxIdx = i;
        }
    }
    return nums.slice(maxIdx, maxIdx + k);
};
